import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Heart } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { getFavourites } from '@/api/favourites';
import { useAuth } from '@/hooks/AuthContext';

/**
 * Wishlist button with real count from the favourites API.
 * Shows the number of favourited items as a badge when authenticated.
 * Falls back to a disabled placeholder for anonymous visitors.
 */
export function WishlistButton() {
  const { user, loading: authLoading } = useAuth();
  const [count, setCount] = useState(0);
  const [fetchError, setFetchError] = useState(false);

  useEffect(() => {
    if (!user || authLoading) {
      setCount(0);
      setFetchError(false);
      return;
    }

    let cancelled = false;

    async function loadCount() {
      try {
        const favourites = await getFavourites();
        if (!cancelled) {
          setCount(Array.isArray(favourites) ? favourites.length : 0);
          setFetchError(false);
        }
      } catch {
        if (!cancelled) {
          setCount(0);
          setFetchError(true);
        }
      }
    }

    void loadCount();
    return () => {
      cancelled = true;
    };
  }, [user, authLoading]);

  if (!user) {
    return (
      <Button
        variant="ghost"
        size="sm"
        className="relative"
        render={<Link to="/login" />}
        aria-label="Wishlist — sign in to view"
      >
        <Heart className="size-4" />
        <span className="ml-1 hidden sm:inline">Wishlist</span>
      </Button>
    );
  }

  return (
    <Button
      variant="ghost"
      size="sm"
      className="relative"
      render={<Link to="/wishlist" />}
      aria-label={`Wishlist — ${fetchError ? 'error loading count' : `${count} items`}`}
    >
      <Heart className="size-4" />
      <span className="ml-1 hidden sm:inline">Wishlist</span>
      {!fetchError && count > 0 && (
        <span
          aria-label={`${count} items in wishlist`}
          className="absolute -right-1 -top-1 flex h-5 w-5 items-center justify-center rounded-full bg-primary text-[10px] font-bold text-primary-foreground"
        >
          {count}
        </span>
      )}
    </Button>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useState,
  useEffect,
  useRef,
  type ReactNode,
} from 'react';
import { X } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface Toast {
  id: string;
  message: string;
  variant?: 'default' | 'success' | 'error';
}

interface ToastContextValue {
  toast: (message: string, variant?: Toast['variant']) => void;
}

const ToastContext = createContext<ToastContextValue>({
  toast: () => {},
});

let toastId = 0;

/**
 * Toast provider — manages toast notifications.
 * Wrap the app to enable toast() calls from anywhere via the hook.
 */
export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const timersRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
    const timer = timersRef.current.get(id);
    if (timer) {
      clearTimeout(timer);
      timersRef.current.delete(id);
    }
  }, []);

  const toast = useCallback(
    (message: string, variant: Toast['variant'] = 'default') => {
      const id = `toast-${++toastId}`;
      setToasts((prev) => [...prev, { id, message, variant }]);
      const timer = setTimeout(() => {
        removeToast(id);
      }, 4000);
      timersRef.current.set(id, timer);
    },
    [removeToast],
  );

  useEffect(() => {
    return () => {
      timersRef.current.forEach((t) => clearTimeout(t));
      timersRef.current.clear();
    };
  }, []);

  const variantClasses: Record<Toast['variant'], string> = {
    default: 'bg-foreground text-background',
    success: 'bg-green-600 text-white',
    error: 'bg-destructive text-destructive-foreground',
  };

  return (
    <ToastContext.Provider value={{ toast }}>
      {children}
      {/* Toast container */}
      <div
        aria-live="polite"
        className="pointer-events-none fixed bottom-4 right-4 z-[100] flex flex-col gap-2"
      >
        {toasts.map((t) => (
          <div
            key={t.id}
            role="status"
            className={cn(
              'pointer-events-auto flex items-center gap-2 rounded-lg px-4 py-2.5 text-sm font-medium shadow-lg transition-all animate-in fade-in slide-in-from-right-4',
              variantClasses[t.variant],
            )}
          >
            <span>{t.message}</span>
            <button
              type="button"
              onClick={() => removeToast(t.id)}
              className="ml-2 rounded-full p-0.5 opacity-70 hover:opacity-100"
              aria-label="Dismiss"
            >
              <X className="size-3.5" />
            </button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

/**
 * Hook to trigger toasts from any component inside a ToastProvider.
 *
 * @example
 * const { toast } = useToast();
 * toast('Added to cart', 'success');
 */
export function useToast(): ToastContextValue {
  return useContext(ToastContext);
}

import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';

/** 404 page shown for unknown routes. */
export function NotFoundPage() {
  return (
    <div className="flex flex-col items-center justify-center gap-4 py-20 text-center">
      <h1 className="text-6xl font-extrabold text-muted-foreground/30">404</h1>
      <h2 className="text-xl font-semibold">Page not found</h2>
      <p className="text-muted-foreground">
        The page you are looking for does not exist or has been moved.
      </p>
      <Button
        render={(props) => <Link to="/" {...props} />}
      >
        Back to Home
      </Button>
    </div>
  );
}

